import{_ as o,o as d,c as t,a2 as a}from"./chunks/framework.M7K9TQZf.js";const g=JSON.parse('{"title":"Prop 규칙","description":"모든 컴포넌트가 하나의 어휘를 공유합니다. size가 md이면 어디서나 같은 높이이고, 이미 이름이 있는 개념에 두 번째 이름을 붙이지 않습니다.","frontmatter":{"title":"Prop 규칙","order":3},"headers":[],"relativePath":"ko/design/prop-conventions.md","filePath":"ko/design/prop-conventions.md","lastUpdated":1788615590000}'),s={name:"ko/design/prop-conventions.md"};function c(r,e,i,l,n,p){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="prop-규칙" tabindex="-1">Prop 규칙 <a class="header-anchor" href="#prop-규칙" aria-label="Permalink to &quot;Prop 규칙&quot;">​</a></h1><p class="plass-lede">모든 컴포넌트가 하나의 어휘를 공유합니다. size가 md이면 어디서나 같은 높이이고, 이미 이름이 있는 개념에 두 번째 이름을 붙이지 않습니다.</p><h2 id="다섯-개의-공통-축" tabindex="-1">다섯 개의 공통 축 <a class="header-anchor" href="#다섯-개의-공통-축" aria-label="Permalink to &quot;다섯 개의 공통 축&quot;">​</a></h2><p><code>src/types.ts</code>에 있고, 스타일이 붙은 모든 컴포넌트가 여기서 가져다 씁니다.</p><table tabindex="0"><thead><tr><th>Prop</th><th>타입</th><th>뜻</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>&#39;solid&#39; | &#39;glass&#39; | &#39;ghost&#39;</code></td><td>표면이 무엇으로 만들어졌는지</td></tr><tr><td><code>size</code></td><td><code>&#39;xs&#39; | &#39;sm&#39; | &#39;md&#39; | &#39;lg&#39; | &#39;xl&#39;</code></td><td>높이와 타입 스케일, 한 묶음으로</td></tr><tr><td><code>color</code></td><td>여섯 역할 이름</td><td>어떤 의미론적 계열인지</td></tr><tr><td><code>density</code></td><td><code>&#39;default&#39; | &#39;compact&#39;</code></td><td>여백, 오직 여백</td></tr><tr><td><code>elevation</code></td><td><code>0 | 1 | 2 | 3</code></td><td>페이지에서 얼마나 떠 있는지</td></tr></tbody></table><h3 id="variant는-재질의-이름입니다" tabindex="-1"><code>variant</code>는 재질의 이름입니다 <a class="header-anchor" href="#variant는-재질의-이름입니다" aria-label="Permalink to &quot;`variant`는 재질의 이름입니다&quot;">​</a></h3><p><code>filled</code>, <code>outlined</code>, <code>text</code>가 아니라 <code>solid</code>, <code>glass</code>, <code>ghost</code>입니다. 이 세 단어는 <a href="./design-language">디자인 언어</a>가 모든 표면에 던지는 질문의 세 가지 답이고, 어떻게 보이는지가 아니라 무엇 <em>인지</em> 로 이름을 붙인 덕분에 애매한 컴포넌트에서도 답이 흔들리지 않습니다.</p><p>같은 단어가 두 가지를 뜻하는 곳은 입력하는 것에 붙은 <code>solid</code> 하나뿐입니다. 거기서는 색 유리판이 아니라 <strong>우물</strong>입니다. <a href="./../components/inputs/text-field#variant">PlTextField</a>를 보세요.</p><h3 id="size는-하나의-결정입니다" tabindex="-1"><code>size</code>는 하나의 결정입니다 <a class="header-anchor" href="#size는-하나의-결정입니다" aria-label="Permalink to &quot;`size`는 하나의 결정입니다&quot;">​</a></h3><p>높이와 타입 스케일은 언제나 함께 움직입니다. <code>size=&quot;md&quot; textSize=&quot;lg&quot;</code> 같은 것은 없습니다. 같은 <code>size</code>인데 높이가 다른 두 컨트롤은 한 줄에서 영원히 맞지 않을 두 컨트롤이기 때문입니다.</p><h3 id="color는-값이-아니라-역할입니다" tabindex="-1"><code>color</code>는 값이 아니라 역할입니다 <a class="header-anchor" href="#color는-값이-아니라-역할입니다" aria-label="Permalink to &quot;`color`는 값이 아니라 역할입니다&quot;">​</a></h3><p>여섯 이름뿐이고 임의 색상은 없습니다. 여섯에 없는 색이 필요한 컴포넌트는 디자인 토큰을 요구하는 것이고, 그건 prop이 아니라 <a href="./color">색</a>의 변경입니다.</p><h3 id="density는-여백입니다" tabindex="-1"><code>density</code>는 여백입니다 <a class="header-anchor" href="#density는-여백입니다" aria-label="Permalink to &quot;`density`는 여백입니다&quot;">​</a></h3><p>높이도 타입 스케일도 절대 건드리지 않습니다. 같은 <code>size</code>의 compact 컨트롤과 default 컨트롤은 같은 기준선에 앉습니다.</p><h3 id="elevation은-기본값이-다르고-그-기본값이-곧-주장입니다" tabindex="-1"><code>elevation</code>은 기본값이 다르고, 그 기본값이 곧 주장입니다 <a class="header-anchor" href="#elevation은-기본값이-다르고-그-기본값이-곧-주장입니다" aria-label="Permalink to &quot;`elevation`은 기본값이 다르고, 그 기본값이 곧 주장입니다&quot;">​</a></h3><p>콘텐츠를 담는 것은 <code>0</code>, 눌리는 것은 <code>1</code>입니다. 키는 시트 <strong>위에</strong> 놓이고, 필드는 시트 <strong>안으로</strong> 파입니다. 컴포넌트의 기본값이 짐작과 다를 때는 그 props 표가 그렇게 말해 줍니다.</p><h2 id="이름-규칙" tabindex="-1">이름 규칙 <a class="header-anchor" href="#이름-규칙" aria-label="Permalink to &quot;이름 규칙&quot;">​</a></h2><p>새 컴포넌트를 만들 때 이 목록으로 점검합니다.</p><ul><li><strong>이미 이름이 있는 개념에 두 번째 이름을 만들지 마세요.</strong> &quot;얼마나 큰지&quot;가 필요하면 <code>size</code>입니다. &quot;어떤 의미론적 색인지&quot;가 필요하면 <code>color</code>입니다. <code>scale</code>이나 <code>tone</code>, <code>intent</code> prop은 어휘를 둘로 쪼개는 일입니다.</li><li><strong>boolean prop은 켜는 상태의 이름을 쓰고</strong> 기본값은 <code>false</code>입니다: <code>loading</code>, <code>readOnly</code>, <code>disabled</code>, <code>fullWidth</code>, <code>multiline</code>, <code>invalid</code>.</li><li><strong>slot은 <code>ReactNode</code>이고 놓이는 자리의 이름을 씁니다</strong>: <code>startIcon</code>, <code>endIcon</code>, <code>label</code>, <code>description</code>, <code>error</code>. <code>renderIcon</code>도 <code>iconLeft</code>도 아닙니다.</li><li><strong><code>left</code>/<code>right</code>가 아니라 <code>start</code>/<code>end</code>.</strong> RTL에서 뒤집히는 쪽은 논리적 이름이고, 물리적 단어는 뒤집히지 않습니다.</li><li><strong>duration과 delay는 CSS 문자열이 아니라 밀리초 숫자입니다.</strong> 타입이 <code>string</code>인 prop은 <code>&#39;0.4s&#39;</code>를 부르고, 그러면 한 화면의 두 컴포넌트가 두 단위로 쓰이게 됩니다.</li><li><strong><code>render</code>가 탈출구이고</strong> 어디서나 같은 이름입니다. Base UI 자신의 prop을 그대로 전달합니다. 표면을 바꾸지 않고 요소만 바꿉니다.</li><li><strong>네이티브 속성은 그대로 전달됩니다.</strong> <code>&lt;input&gt;</code>을 감싸는 컴포넌트는 위 축과 이름이 겹치는 것(<code>color</code>, <code>size</code>)을 뺀 모든 <code>&lt;input&gt;</code> 속성을 받습니다.</li></ul><h2 id="키를-묶기" tabindex="-1">키를 묶기 <a class="header-anchor" href="#키를-묶기" aria-label="Permalink to &quot;키를 묶기&quot;">​</a></h2><p><code>PlTextField</code>, <code>PlNumberField</code>, <code>PlOtpField</code>, <code>PlCombobox</code>, <code>PlSelect</code>는 <strong><code>hotKeys</code></strong> map을 받습니다. chord와, 그 chord를 눌렀을 때 일어나는 일입니다.</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlTextField</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hotKeys</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Mod+Enter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: save, Escape: cancel }} /&gt;</span></span></code></pre></div><p>다섯 곳 모두에 세 가지 규칙이 적용됩니다.</p><ul><li><strong>chord는 키캡을 쓰는 방식으로 씁니다</strong>: <a href="./../components/display/hot-keys"><code>PlHotKeys</code></a>가 그리는 것과 같은 vocabulary입니다. <code>Mod</code>는 platform에 따라 정해지고(Mac에서는 ⌘, 그 밖에서는 <kbd>Ctrl</kbd>), <code>Esc</code>, <code>Return</code>, <code>Cmd</code>, <code>Option</code>도 키캡과 같은 키로 접힙니다. 컴포넌트가 <strong>보여 주는</strong> 단축키와 <strong>묶는</strong> 단축키가 한 문자열이 아니면, 화면의 키캡은 아무도 확인하지 않은 주장이 됩니다.</li><li><strong>modifier는 양방향으로 검사합니다.</strong> <code>Enter</code>는 <kbd>Shift</kbd>+<kbd>Enter</kbd>에 반응하지 않습니다. Enter로 저장하는 필드가 Enter로 끝나는 모든 chord에서 저장되지는 않는다는 뜻입니다.</li><li><strong>맞는 chord는 소비됩니다.</strong> handler가 실행되고 키는 더 이상 가지 않습니다. 컨트롤 자신의 키 처리에도, form에도, 그 위의 dialog에도. 글자가 아니라 chord를 묶으세요. <code>{ a: … }</code>인 필드는 <code>a</code>를 칠 수 없습니다.</li></ul><div class="plass-fw" data-fw="react"><p><code>hotKeys</code>는 감싸는 stack이 아니라 <strong>control</strong>에 붙습니다. chord에 답하는 것은 focus를 쥔 쪽이기 때문입니다. <code>onKeyDown</code>을 대체하는 것이 아니라 그 위의 편의입니다. raw handler는 그대로 같은 요소로 전달되고, <strong>먼저</strong> 실행됩니다. 거기서 <code>preventDefault()</code>를 부르면 map은 건너뜁니다.</p></div><div class="plass-fw" data-fw="flutter"><p>map은 위젯 자신의 키 처리보다 focus node에 더 가깝게 묶입니다. 그래서 caller가 컨트롤에서 키를 가져올 수 있습니다. <code>PlSelect</code>만은 감싸는 것으로 안 되는데(<code>FocusableActionDetector</code>가 Enter를 필드가 감쌀 수 있는 그 어떤 것보다 가깝게 묶기 때문입니다) 그래서 map이 Enter를 요구하면 trigger가 <strong>물러납니다</strong>.</p><p>이 아래에 <code>onKeyDown</code>은 없습니다. chord map보다 세밀한 키 처리가 필요한 위젯은 필드를 자기 <code>Focus</code>로 감쌉니다.</p></div><h2 id="바깥에서-컴포넌트에-스타일-입히기" tabindex="-1">바깥에서 컴포넌트에 스타일 입히기 <a class="header-anchor" href="#바깥에서-컴포넌트에-스타일-입히기" aria-label="Permalink to &quot;바깥에서 컴포넌트에 스타일 입히기&quot;">​</a></h2><div class="plass-fw" data-fw="react"><p>채널은 넷이고, 서로 대체되지 않습니다. 이 순서로 고르세요.</p><h3 id="_1-classname-레이아웃용" tabindex="-1">1. <code>className</code>, 레이아웃용 <a class="header-anchor" href="#_1-classname-레이아웃용" aria-label="Permalink to &quot;1. `className`, 레이아웃용&quot;">​</a></h3><p><code>className</code>은 읽는 사람이 손가락으로 가리키며 &quot;이 컴포넌트&quot;라고 부를 요소 하나에 붙습니다. <code>PlButton</code>의 <code>&lt;button&gt;</code>, <code>PlModal</code>의 시트, field의 stack입니다. 컴포넌트 자신의 class를 대체하지 않고 함께 적용되며, 어느 요소인지는 각 컴포넌트의 Props 절에 적혀 있습니다.</p><p>컴포넌트가 어디에 놓이고 얼마나 자리를 차지하는지(<code>w-full</code>, margin, grid 위치)에 맞는 채널입니다. 라이브러리가 자기 자신에게 지정하지 않는 속성들이라 다툴 상대가 없습니다.</p><h3 id="_2-classnames-classname이-닿지-않는-부분용" tabindex="-1">2. <code>classNames</code>, <code>className</code>이 닿지 않는 부분용 <a class="header-anchor" href="#_2-classnames-classname이-닿지-않는-부분용" aria-label="Permalink to &quot;2. `classNames`, `className`이 닿지 않는 부분용&quot;">​</a></h3><p>어떤 컴포넌트는 하나보다 많이 그립니다. field는 label과 그 아래 두 줄을 그리고, portal로 뜨는 표면은 뒤에 scrim을 깝니다. <code>classNames</code>는 그 부분들에만 닿는 map입니다. 컴포넌트 자신의 표면은 prop 하나만 갖기 때문에, 둘 중 어느 쪽이 이기는지 물을 일이 없습니다.</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlTextField</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  label</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Email&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  className</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;w-full&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  classNames</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ control: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;font-mono&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, error: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;italic&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>키는 어디에 나오든 같은 부분을 뜻합니다. 라벨 있는 컨트롤에서는 <code>label</code>, <code>control</code>, <code>description</code>, <code>error</code>이고, portal 표면에서는 <code>backdrop</code>입니다.</p><h3 id="_3-토큰-컴포넌트가-이미-칠한-것을-바꿀-때" tabindex="-1">3. 토큰, 컴포넌트가 이미 칠한 것을 바꿀 때 <a class="header-anchor" href="#_3-토큰-컴포넌트가-이미-칠한-것을-바꿀-때" aria-label="Permalink to &quot;3. 토큰, 컴포넌트가 이미 칠한 것을 바꿀 때&quot;">​</a></h3><p><strong>항상 통하는 채널이고</strong>, 그 이유는 그냥 믿기보다 알아 두는 편이 낫습니다.</p><p>라이브러리는 테두리와 그림자, focus ring, fill을 Tailwind의 <em>arbitrary property</em>(<code>[box-shadow:var(--p-elev),var(--p-lift)]</code> 같은 형태)로 씁니다. Tailwind는 이런 클래스를 생성된 스타일시트의 <strong>맨 뒤</strong>에 정렬하고, 두 class 중 어느 쪽이 이기는지는 스타일시트가 정합니다. 뒤에 <code>shadow-none</code>을 덧붙이면 파일에서는 더 <strong>앞</strong>에 놓이므로 집니다.</p><p>그 아래의 custom property는 지지 않습니다. inline <code>style</code>은 어떤 class보다도 강하기 때문입니다. <a href="./color#react에서-토큰-지정하기">React에서 토큰 지정하기</a>를 보세요.</p><h3 id="그냥-붙인-classname의-한계" tabindex="-1">그냥 붙인 <code>className</code>의 한계 <a class="header-anchor" href="#그냥-붙인-classname의-한계" aria-label="Permalink to &quot;그냥 붙인 `className`의 한계&quot;">​</a></h3><p>class 속성 안에서의 순서는 아무 의미가 없습니다. 결정하는 것은 생성된 스타일시트 안에서의 순서이고, Tailwind의 정렬은 <em>이름</em> 기준입니다. 숫자 스케일은 오름차순, 나머지는 알파벳순. 호출자의 의도와는 아무 관계가 없습니다.</p><table tabindex="0"><thead><tr><th>컴포넌트가 쓰는 것</th><th>당신이 쓰는 것</th><th>이기는 쪽</th></tr></thead><tbody><tr><td><code>text-sm</code> (<code>size=&quot;sm&quot;</code>)</td><td><code>text-lg</code></td><td><strong>컴포넌트</strong></td></tr><tr><td><code>bg-transparent</code> (<code>variant=&quot;ghost&quot;</code>)</td><td><code>bg-red-500</code></td><td><strong>컴포넌트</strong></td></tr><tr><td><code>w-full</code> (<code>fullWidth</code>)</td><td><code>w-auto</code></td><td><strong>컴포넌트</strong></td></tr><tr><td><code>h-10</code> (<code>size=&quot;md&quot;</code>)</td><td><code>h-8</code></td><td><strong>컴포넌트</strong></td></tr><tr><td><code>[box-shadow:…]</code></td><td><code>shadow-none</code></td><td><strong>컴포넌트</strong></td></tr><tr><td><code>h-10</code></td><td><code>h-12</code></td><td>당신</td></tr><tr><td><code>rounded-(--plass-radius-md)</code></td><td><code>rounded-3xl</code></td><td>당신</td></tr><tr><td><code>p-4</code></td><td><code>px-8</code></td><td>당신</td></tr></tbody></table><p>확실한 우회로는 둘입니다.</p><ul><li><strong>토큰.</strong> 바로 위 절에서 설명한 방법입니다. arbitrary property에 닿는 유일한 채널이기도 합니다.</li><li><strong><code>!</code> 수식자</strong>: <code>shadow-none!</code>, <code>text-lg!</code>. 라이브러리에는 <code>!important</code>가 한 곳도 없으므로 important 유틸리티는 언제나 이깁니다. 선택이 아닌 곳이 하나 있는데, <code>.plass-link.plass-link</code> 규칙이 단일 class를 순서와 무관하게 이기는 <code>PlTextLink</code>입니다.</li></ul><h3 id="import한-스타일시트" tabindex="-1">import한 스타일시트 <a class="header-anchor" href="#import한-스타일시트" aria-label="Permalink to &quot;import한 스타일시트&quot;">​</a></h3><table tabindex="0"><thead><tr><th>import</th><th>충돌을 결정하는 것</th></tr></thead><tbody><tr><td><code>plass-ui/tailwind.css</code> 또는 <code>plass-ui/css/*.css</code></td><td>위 표대로 Tailwind의 정렬. 당신의 class와 컴포넌트의 class가 한 번의 패스에서 생성됩니다</td></tr><tr><td><code>plass-ui/styles.css</code></td><td><strong><code>@import</code> 순서.</strong> 패키지의 CSS는 이미 컴파일된 것이라 당신의 Tailwind 빌드에 참여할 수 없습니다. 당신의 스타일시트보다 <em>앞에</em> import하지 않으면 그 안의 모든 것을 이겨 버립니다</td></tr></tbody></table><h3 id="_4-render-요소-자체가-잘못됐을-때" tabindex="-1">4. <code>render</code>, 요소 자체가 잘못됐을 때 <a class="header-anchor" href="#_4-render-요소-자체가-잘못됐을-때" aria-label="Permalink to &quot;4. `render`, 요소 자체가 잘못됐을 때&quot;">​</a></h3><p>Base UI 자신의 prop이고, 의미가 있는 곳에서 그대로 전달됩니다. <code>&lt;PlButton render={&lt;a href=&quot;/pricing&quot; /&gt;}&gt;</code>이 그 예입니다. 표면을 바꾸지 않고 요소만 바꾸는데, 이건 CSS로는 아무리 해도 못 하는 일입니다.</p></div><h2 id="상태-prop의-규칙" tabindex="-1">상태 prop의 규칙 <a class="header-anchor" href="#상태-prop의-규칙" aria-label="Permalink to &quot;상태 prop의 규칙&quot;">​</a></h2><p>상태는 셋이고 각자 자기 축을 가집니다. 그중 하나와 겹치는 네 번째는 스타일이 아니라 API의 버그입니다.</p><table tabindex="0"><thead><tr><th>상태</th><th>네이티브 속성</th><th>Focus</th><th>핸들러 실행</th></tr></thead><tbody><tr><td><code>disabled</code></td><td>예</td><td>잃음</td><td>아니오</td></tr><tr><td><code>readOnly</code></td><td><code>aria-disabled</code></td><td>유지</td><td>아니오</td></tr><tr><td><code>loading</code></td><td><code>aria-disabled</code></td><td>유지</td><td>아니오</td></tr></tbody></table><p><code>loading</code>과 <code>readOnly</code>가 focus를 유지하는 것은 의도된 것입니다. tab 순서에서 빠지면 키보드 사용자는 페이지에서 자기 위치를 잃습니다.</p>',32)])])}const u=o(s,[["render",c]]);export{g as __pageData,u as default};
